        foreach ($locations as $locationData) {
            // opening_hoursとamenityを分離
            $openingHoursData = $locationData['opening_hours'] ?? [];
            $amenityData = $locationData['amenity'] ?? [];
            unset($locationData['opening_hours'], $locationData['amenity']);

            // Locationを作成
            $location = Location::factory()->create($locationData);

            // Amenityを作成
            if (!empty($amenityData)) {
                Amenity::create(array_merge(['location_id' => $location->id], $amenityData));
            } else {
                Amenity::factory()->create(['location_id' => $location->id]);
            }

            // OpeningHoursを作成
            if (!empty($openingHoursData)) {
                foreach ($openingHoursData as $hourData) {
                    OpeningHour::create(array_merge(['location_id' => $location->id], $hourData));
                }
            }

            // レビューと画像を作成
            $reviews = UserReview::factory(3)->create([
                'location_id' => $location->id,
            ]);

            foreach ($reviews as $review) {
                ReviewImage::factory(3)->create([
                    'user_review_id' => $review->id,
                    'location_id' => $location->id,
                ]);
            }
        }
    }
